// check panics with a failure if err is not nil (Run recovers it). Small,
// so that it inlines into hot loops; the error path is out of line.
func check(err error) {
	if err != nil {
		fail(err)
	}
}

// fail panics with err, naming the caller's line.
func fail(err error) {
	_, file, line, _ := runtime.Caller(2)
	panic(failure{fmt.Errorf("%s:%d: %w", filepath.Base(file), line, err)})
}

// failf panics with a failed consistency check, like cbench's.
func failf(format string, args ...any) {
	panic(failure{fmt.Errorf(format, args...)})
}

// goCheck runs fn on a new goroutine (a reader of read or mixed) and
// stores the first failure in *errp instead of crashing the process.
func goCheck(done func(), errp *atomic.Pointer[error], fn func()) {
	go func() {
		defer done()
		defer func() {
			if r := recover(); r != nil {
				f, ok := r.(failure)
				if !ok {
					panic(r)
				}
				errp.CompareAndSwap(nil, &f.err)
			}
		}()
		fn()
	}()
}

// rethrow turns a failure stored by goCheck into a panic on the Run
// goroutine.
func rethrow(errp *atomic.Pointer[error]) {
	if e := errp.Load(); e != nil {
		panic(failure{*e})
	}
}

// sink keeps the sums of read workloads alive (cbench's volatile sink,
// Rust's black_box).
