// heapAllocs is the number of Go heap allocations so far. ReadMemStats
// stops the world, but it is exact (runtime/metrics counts small objects
// only when their span is refilled, so short repetitions read 0); it is
// called outside the timed part of a repetition.
func heapAllocs() uint64 {
	var ms runtime.MemStats
	runtime.ReadMemStats(&ms)
	return ms.Mallocs
}

// timer measures one repetition: wall time (monotonic) and Go heap
// allocations.
type timer struct {
	t0     time.Time
	allocs uint64
}

func startTimer() timer {
	a := heapAllocs()
	return timer{t0: time.Now(), allocs: a}
}

// samples are the timed repetitions of one workload.
type samples []run.Sample

// record records iteration it (0 is the warm-up, not recorded) that
// started at t and did ops operations.
func (s *samples) record(it int, t timer, ops int) {
	ns := uint64(time.Since(t.t0).Nanoseconds())
	allocs := heapAllocs() - t.allocs
	if it > 0 {
		*s = append(*s, run.Sample{NS: ns, Ops: uint64(ops), Allocs: allocs})
	}
}

// recordElapsed is record for a workload that measured its own time.
func (s *samples) recordElapsed(it int, d time.Duration, allocs uint64, ops int) {
	if it > 0 {
		*s = append(*s, run.Sample{NS: uint64(d.Nanoseconds()), Ops: uint64(ops), Allocs: allocs})
	}
}

// ---- environment helpers (cbench.c: reset_dir, open_env, open_dbi) ----

func resetDir(dir string) {
	check(os.MkdirAll(dir, 0o755))
	for _, f := range []string{"data.mdb", "lock.mdb"} {
		if err := os.Remove(filepath.Join(dir, f)); err != nil && !errors.Is(err, os.ErrNotExist) {
			fail(err)
		}
	}
}

// openEnv opens an environment as cbench does: 4 GiB map, 4 DBs, 126
// readers. (lmdb-go always adds MDB_NOTLS; cbench uses C's default TLS
// mode, rlmdb behaves like MDB_NOTLS.)
func openEnv(dir string, flags uint) *lmdb.Env {
	env, err := lmdb.NewEnv()
	check(err)
	check(env.SetMapSize(mapSize))
	check(env.SetMaxDBs(4))
	check(env.SetMaxReaders(126))
	check(env.Open(dir, flags, 0o644))
	return env
}

// openDBI creates DB name ("" is the main DB) with flags and returns its
// handle.
func openDBI(env *lmdb.Env, name string, flags uint) lmdb.DBI {
	txn := beginWrite(env)
	var db lmdb.DBI
	var err error
	if name == "" {
		db, err = txn.OpenRoot(flags | lmdb.Create)
	} else {
		db, err = txn.OpenDBI(name, flags|lmdb.Create)
	}
	check(err)
	check(txn.Commit())
	return db
}

// beginWrite begins a top-level write transaction. Only the Run
// goroutine, which is locked to its thread, calls it.
func beginWrite(env *lmdb.Env) *lmdb.Txn {
	txn, err := env.BeginTxn(nil, 0)
	check(err)
	return txn
}

// beginRead begins a read transaction whose values are zero-copy slices
// into the map (RawRead), as in C and rlmdb; lmdb-go copies by default.
// (No workload uses an op after which C leaves the key unset, such as
// FirstDup, for which lmdb-go v1 with RawRead panics.)
func beginRead(env *lmdb.Env) *lmdb.Txn {
	txn, err := env.BeginTxn(nil, lmdb.Readonly)
	check(err)
	txn.RawRead = true
	return txn
}

// putKeys is put_keys of cbench.c: puts keys[order[j]] (or keys[j]) for
// j < n, vlen-byte values at ValOff(i + vsalt), committing every batch
// puts.
func putKeys(env *lmdb.Env, db lmdb.DBI, pool []byte, keys data.Keys, order []uint32,
	n, vlen int, vsalt uint64, flags uint, batch int) {
	var txn *lmdb.Txn
	for j := 0; j < n; j++ {
		i := j
		if order != nil {
			i = int(order[j])
		}
		if txn == nil {
			txn = beginWrite(env)
		}
		check(txn.Put(db, keys.Key(i), data.Value(pool, uint64(i)+vsalt, vlen), flags))
		if (j+1)%batch == 0 {
			check(txn.Commit())
			txn = nil
		}
	}
	if txn != nil {
		check(txn.Commit())
	}
}

// buildRand returns a fresh environment holding the rand_put data set.
func buildRand(dir string, pool []byte, keys data.Keys) (*lmdb.Env, lmdb.DBI) {
	resetDir(dir)
	env := openEnv(dir, lmdb.NoSync)
	db := openDBI(env, "", 0)
	putKeys(env, db, pool, keys, nil, keys.Len(), data.ValLen, 0, 0, batch)
	return env, db
}

// scanAll walks the whole DB with op (Next or Prev) in txn; returns the
// number of entries and a sum of their first key bytes and value lengths.
func scanAll(txn *lmdb.Txn, db lmdb.DBI, op uint) (cnt int, sum uint64) {
	cur, err := txn.OpenCursor(db)
	check(err)
	for {
		k, v, err := cur.Get(nil, nil, op)
		if err != nil {
			if lmdb.IsNotFound(err) {
				break
			}
			fail(err)
		}
		cnt++
		sum += uint64(k[0]) + uint64(len(v))
	}
	cur.Close()
	return cnt, sum
}
